UPDATE public.productos SET
  descripcion_larga_es = $d$El ítem catalogado como Carrito de Lavado SKH041 Saikang en IME incluye PDF oficial relacionado con soporte de perfusión SKH041(1)-2 (página fabricante SKH0411-2 IV stand). Confirme equivalencia de referencia con IME antes de pedido.

Datos del PDF SKH041(1)-2: soporte IV 4 ganchos; altura base 1150–1900 mm; ruedas 50 mm (2 con freno); carga máxima 5 kg; tubo acero inoxidable; base nylon 5 brazos.

Referencia: https://saikangmedical.com/en/product/skh0411-2-iv-stand/$d$,
  descripcion_larga_en = $d$The IME catalog entry Washing Cart SKH041 Saikang includes an official PDF for infusion stand SKH041(1)-2 (manufacturer page SKH0411-2 IV stand). Confirm SKU mapping with IME before ordering.

SKH041(1)-2 PDF data: 4-hook IV support; base height 1150–1900 mm; 50 mm casters (2 with brake); max load 5 kg; stainless steel tube; 5-leg nylon base.

Reference: https://saikangmedical.com/en/product/skh0411-2-iv-stand/$d$,
  especificaciones = $j$[{"clave":"Modelo en PDF","grupo":"Ficha PDF Saikang","valor":"SKH041(1)-2 soporte perfusión IV"},{"clave":"Altura base","grupo":"Ficha PDF Saikang","valor":"1150–1900 mm"},{"clave":"Carga máxima","grupo":"Ficha PDF Saikang","valor":"5 kg"},{"clave":"Ruedas","grupo":"Ficha PDF Saikang","valor":"50 mm (2 pulgadas); 2 con freno"},{"clave":"Ganchos","grupo":"Ficha PDF Saikang","valor":"4 acero inoxidable"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Elevación: 810-1300 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Base 5 ruedas Φ500 mm"}]$j$::jsonb,
  aplicaciones_es = ARRAY(SELECT jsonb_array_elements_text($j$["Infusión intravenosa","Hospitalización","Urgencias"]$j$::jsonb)),
  aplicaciones_en = ARRAY(SELECT jsonb_array_elements_text($j$["IV infusion","Inpatient care","Emergency care"]$j$::jsonb)),
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Soporte perfusión 4 ganchos documentado en PDF Saikang","Altura regulable 1150–1900 mm (ficha)","Carga máxima 5 kg según ficha técnica","PDF oficial descargable vía IME Colombia"],"beneficios_en":["4-hook IV support documented in Saikang PDF","Adjustable height 1150–1900 mm (datasheet)","5 kg max load per datasheet","Official PDF via IME Colombia"],"valor_es":"Carrito de Lavado SKH041 Saikang: landing con PDF SKH041(1)-2 y aclaración de código; cotización IME.","valor_en":"Washing Cart SKH041 Saikang: landing with SKH041(1)-2 PDF and code note; IME quote.","preguntas_frecuentes_es":[{"q":"¿El PDF SKH041 coincide con el nombre Carrito de Lavado?","a":"El PDF es SKH041(1)-2 soporte de perfusión; el SKU IME es SKH041. Confirme con IME."},{"q":"¿Rango de altura en ficha?","a":"1150–1900 mm."},{"q":"¿Carga máxima?","a":"5 kg según ficha Saikang."},{"q":"¿Dónde descargo la ficha?","a":"PDF en esta landing IME."},{"q":"¿Cómo cotizo SKH041?","a":"Indique Carrito de Lavado SKH041 Saikang a IME Colombia."}],"preguntas_frecuentes_en":[{"q":"Does SKH041 PDF match Washing Cart name?","a":"PDF is SKH041(1)-2 IV stand; IME SKU is SKH041. Confirm with IME."},{"q":"Height range?","a":"1150–1900 mm."},{"q":"Max load?","a":"5 kg per Saikang datasheet."},{"q":"Download datasheet?","a":"PDF on this IME landing."},{"q":"Quote SKH041?","a":"Request Washing Cart SKH041 Saikang from IME Colombia."}],"seo_keywords_es":["SKH041 Saikang","SKH0411-2 ficha técnica","soporte perfusión Colombia","IME"],"seo_keywords_en":["SKH041 Saikang","SKH0411-2 datasheet","IV stand Colombia","IME"],"ficha_fabricante":{"fabricante":"Saikang","idioma":"en","url_origen":"https://saikangmedical.com/wp-content/uploads/2026/10/SAIKANG_SKH0411-2.pdf","descargada":null,"sin_pdf":true}}$j$::jsonb
